public class XorCipherTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String str(int[] values) {
        return values == null ? "null" : java.util.Arrays.toString(values);
    }

    public static void main(String[] args) {
        check("apply(A, B)", "[3]", str(XorCipher.apply("A", "B")));
        check("apply(Hi, k)", "[35, 2]", str(XorCipher.apply("Hi", "k")));
        check("apply(empty text)", "[]", str(XorCipher.apply("", "k")));
        check("apply with empty key", "null", str(XorCipher.apply("abc", "")));
        check("apply with null key", "null", str(XorCipher.apply("abc", null)));
        check("key cycles", "[0, 0, 0, 0]", str(XorCipher.apply("abab", "ab")));
        check("toText({72,105})", "Hi", XorCipher.toText(new int[] {72, 105}));
        check("toText(null)", "", XorCipher.toText(null));

        String secret = "Attack at dawn!";
        String key = "key";
        String scrambled = XorCipher.toText(XorCipher.apply(secret, key));
        check("scrambled differs from plain text", false, secret.equals(scrambled));
        check("round trip", secret, XorCipher.toText(XorCipher.apply(scrambled, key)));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

