public class XorCipher {

    public static int[] apply(String text, String key) {
        if (text == null || key == null || key.isEmpty()) {
            return null;
        }
        int[] out = new int[text.length()];
        for (int i = 0; i < text.length(); i++) {
            int textCode = text.charAt(i);
            int keyCode = key.charAt(i % key.length());
            out[i] = (textCode ^ keyCode) & 0xFF;
        }
        return out;
    }

    public static String toText(int[] codes) {
        if (codes == null) {
            return "";
        }
        StringBuilder sb = new StringBuilder();
        for (int code : codes) {
            sb.append((char) code);
        }
        return sb.toString();
    }
}
